from pathlib import Path

p = Path('NAYAHUB.html')
s = p.read_text(encoding='utf-8')
assert '<title>NayaNET — Intelligent Hub V7</title>' in s
assert 'id="page-notes"' in s and 'id="page-reports"' in s

css = r'''
<style id="nayanet-v7-refinement-style">
/* V7 SURGICAL REFINEMENT — preserves the existing architecture */
.btn,.filter,.mailTab,.switch,.connectionPill,.nav button,.mobileNav button,.nayanet-ecosystem-bar a,.nayanet-feature-bar a{border-width:2px}
.btn{border-color:#8b63ff66;box-shadow:inset 0 1px #fff6,0 9px 20px #0009,0 0 15px #6675ff16}.btn.green{border-color:#55e39a88}.btn.blue{border-color:#55b9ee88}.btn.purple{border-color:#b66cff99}.btn.gold{border-color:#e8c76688}
.btn:hover,.btn:focus-visible{border-color:#b99aff;box-shadow:inset 0 1px #fff8,0 16px 32px #000b,0 0 28px #6675ff2c}.btn.green:hover,.btn.green:focus-visible{border-color:#55e39a;box-shadow:inset 0 1px #fff8,0 16px 32px #000b,0 0 28px #55e39a30}.btn.blue:hover,.btn.blue:focus-visible{border-color:#55b9ee;box-shadow:inset 0 1px #fff8,0 16px 32px #000b,0 0 28px #55b9ee30}.btn.purple:hover,.btn.purple:focus-visible{border-color:#d86cff;box-shadow:inset 0 1px #fff8,0 16px 32px #000b,0 0 28px #d86cff30}
.nav button{border-color:#8b63ff42}.nav button:hover{border-color:#9c78ff99}.nav button.active{border-color:#d86cffaa;box-shadow:inset 0 1px #fff7,0 14px 32px #000a,0 0 30px #d86cff22}.filter,.mailTab{border-color:#8b63ff55;color:#cfc8db}.filter:hover,.mailTab:hover{border-color:#a989ff}.filter.active,.mailTab.active{border-color:#55e39a;box-shadow:0 0 18px #55e39a20}
.switch{border-color:#8b63ff88;background:#11101a;box-shadow:0 0 14px #6675ff18}.toggle.on .switch{border-color:#55e39a;box-shadow:0 0 18px #55e39a28}.toggle.on .switch i{background:var(--green);box-shadow:0 0 16px #55e39a}.connectionPill{border-color:#8b63ff66}.connectionPill:focus-visible{border-color:#55e39a}.nayanet-ecosystem-bar a,.nayanet-feature-bar a{border-color:#8b63ff66}.nayanet-ecosystem-bar a:hover,.nayanet-feature-bar a:hover{border-color:#d86cff}
#page-notes .compose,#page-notes #newNote{display:none!important}
.nh-note-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin:0 0 18px;padding:18px 20px;border:2px solid #6675ff55;border-radius:20px;background:linear-gradient(145deg,#12121a,#09090d);box-shadow:inset 0 1px #fff4,0 18px 40px #000a}.nh-note-head b{font-size:8px;letter-spacing:.16em;color:#a995ff}.nh-note-head strong{display:block;font-size:20px;letter-spacing:-.035em;margin-top:6px}.nh-note-head span{color:#aaa4b1;font-size:10px;line-height:1.5;max-width:650px;text-align:right}
.nh-timefilters{display:flex;gap:7px;flex-wrap:wrap;margin:0 0 16px}.nh-timefilter{min-height:38px;padding:0 13px;border:2px solid #8b63ff55;border-radius:11px;background:#09090e;color:#c8c1d3;font-size:8px;font-weight:1000;letter-spacing:.07em}.nh-timefilter:hover{border-color:#b18cff}.nh-timefilter.active{border-color:#55e39a;color:#fff;background:#0b1711;box-shadow:0 0 20px #55e39a18}
.nh-group{margin:24px 0}.nh-group-title{display:flex;align-items:center;gap:9px;margin-bottom:10px;color:#cfc9d6;font-size:8px;font-weight:1000;letter-spacing:.15em}.nh-group-title i{width:7px;height:7px;border-radius:50%;background:#d86cff;box-shadow:0 0 12px #d86cff}.nh-memory-card{border:2px solid #8b63ff42;border-radius:18px;background:linear-gradient(145deg,#14141b,#09090d);box-shadow:inset 0 1px #fff3,0 15px 32px #0009;margin-bottom:10px;overflow:hidden}.nh-memory-card:hover{border-color:#a989ff88}.nh-memory-top{display:flex;justify-content:space-between;gap:12px;padding:13px 16px;border-bottom:1px solid #ffffff12}.nh-memory-top span{font-size:8px;color:#aaa4b0}.nh-memory-top b{font-size:7px;padding:5px 8px;border:1px solid #55e39a66;border-radius:999px;color:#bfffd8}.nh-memory-body{padding:15px 16px}.nh-memory-body h3{font-size:15px;margin:0 0 6px}.nh-memory-body p{font-size:11px;line-height:1.6;color:#d4ced9;margin:0}.nh-perspectives{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;padding:0 16px 15px}.nh-perspective{padding:10px;border:1px solid #ffffff14;border-radius:11px;background:#08080c}.nh-perspective b{display:block;font-size:6px;letter-spacing:.12em;margin-bottom:5px}.nh-perspective span{display:block;color:#a9a3af;font-size:8px;line-height:1.45}
.nh-report{margin:24px 0;border:2px solid #55e39a55;border-radius:22px;background:linear-gradient(145deg,#101a15,#09090d);box-shadow:inset 0 1px #fff3,0 22px 45px #000a;overflow:hidden}.nh-report-head{padding:18px 20px;border-bottom:1px solid #ffffff12;display:flex;justify-content:space-between;gap:15px;align-items:center}.nh-report-head h2{font-size:20px;letter-spacing:-.04em;margin:0}.nh-report-head span{font-size:7px;color:#55e39a;font-weight:1000;letter-spacing:.12em}.nh-report-state{margin:14px 20px 0;padding:10px 12px;border:1px solid #e8c76666;border-radius:10px;color:#f1db89;font-size:8px;font-weight:900;letter-spacing:.08em}.nh-report-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;padding:14px 20px 20px}.nh-report-card{padding:14px;border:1px solid #ffffff16;border-radius:14px;background:#08090b}.nh-report-card h3{font-size:8px;letter-spacing:.13em;margin:0 0 8px}.nh-report-card p{font-size:10px;color:#c9c3ce;line-height:1.6;margin:0}.nh-empty{padding:34px 20px;text-align:center;border:2px dashed #8b63ff44;border-radius:18px;color:#a8a2ae}.nh-empty strong{display:block;color:#fff;font-size:16px;margin-bottom:6px}.nh-empty span{font-size:10px;line-height:1.6}
@media(max-width:900px){.nh-note-head{display:block}.nh-note-head span{display:block;text-align:left;margin-top:8px}.nh-perspectives{grid-template-columns:1fr 1fr}.nh-report-grid{grid-template-columns:1fr}.nh-memory-top{align-items:flex-start}.nh-timefilter{min-height:40px}.nh-report-head{display:block}.nh-report-head span{display:block;margin-top:7px}}@media(max-width:520px){.nh-perspectives{grid-template-columns:1fr}.nh-memory-top{display:block}.nh-memory-top b{display:inline-block;margin-top:8px}.main{padding-left:12px;padding-right:12px}.nh-note-head,.nh-report{border-radius:17px}}
</style>
'''
if 'id="nayanet-v7-refinement-style"' not in s:
    s=s.replace('</head>',css+'</head>',1)

s=s.replace('<button data-page="intelligence"><span class="ico">✦</span>Intelligence</button>','<button data-page="intelligence"><span class="ico">✦</span>Intelligence Library</button>')
s=s.replace("intelligence:'Intelligence'","intelligence:'Intelligence Library'")
s=s.replace('<div class="eyebrow">THE INTELLIGENCE LAYER</div><h1>Intelligence</h1><p>One event. Four perspectives. A living system that shows what is known, what is interpreted, and what is still waiting.</p>','<div class="eyebrow">THE INTELLIGENCE LIBRARY</div><h1>Intelligence Library</h1><p>Your searchable Q&amp;A and reference layer for how the Hub works, what it knows, what compounds, and where your intelligence lives.</p>')

marker='</section>\n<section class="page" id="page-intelligence">'
if 'id="nhReportPage"' not in s:
    s=s.replace(marker,'<div class="nh-report-page" id="nhReportPage"></div></section>\n<section class="page" id="page-intelligence">',1)

js=r'''
<script id="nayanet-v7-refinement-runtime">
(function(){'use strict';
const KEY='nayanet_v7_live_notes';const getNotes=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'[]')}catch(e){return[]}};const esc=s=>String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\':'&#92;','"':'&quot;'}[c]||c));const dt=iso=>new Date(iso);const fmtTime=iso=>new Intl.DateTimeFormat(undefined,{hour:'numeric',minute:'2-digit'}).format(dt(iso));const fmtDay=iso=>new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'}).format(dt(iso));const fmtMonth=iso=>new Intl.DateTimeFormat(undefined,{month:'long',year:'numeric'}).format(dt(iso));const dayKey=iso=>{let d=dt(iso);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};const monthKey=iso=>{let d=dt(iso);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')};const yearKey=iso=>String(dt(iso).getFullYear());const hourKey=iso=>dayKey(iso)+' · '+fmtTime(iso);let mode='DAY';
function noteSummary(n){return String(n.text||'').replace(/\s+/g,' ').trim()}function groupLabel(n){if(mode==='HOUR')return hourKey(n.createdAt);if(mode==='MONTH')return fmtMonth(n.createdAt);if(mode==='YEAR')return yearKey(n.createdAt);return fmtDay(n.createdAt)}function groupKey(n){if(mode==='HOUR')return hourKey(n.createdAt);if(mode==='MONTH')return monthKey(n.createdAt);if(mode==='YEAR')return yearKey(n.createdAt);return dayKey(n.createdAt)}
function perspective(n,label){const t=noteSummary(n);if(label==='HUMAN')return t||'Human source text preserved.';if(label==='NAYA')return 'Pending production intelligence service. No AI interpretation is fabricated.';if(label==='MACHINE')return 'event_id '+(n.id||'unknown')+' · '+n.type+' · '+n.createdAt+' · local_persisted · private';return 'Chronologically preserved for later synthesis and compounding.'}
function renderMemory(){const root=document.getElementById('noteList');if(!root)return;const notes=getNotes().sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));const q=(document.getElementById('noteSearch')?.value||'').toLowerCase().trim();const type=document.querySelector('#filters .filter.active')?.dataset.filter||'ALL';let filtered=notes.filter(n=>(type==='ALL'||n.type===type)&&(!q||String(n.text||'').toLowerCase().includes(q)));if(!filtered.length){root.innerHTML='<div class="nh-empty"><strong>No matching intelligence.</strong><span>Your Smart Notes memory is intentionally truthful. Nothing is invented to fill the space.</span></div>';return}const groups=new Map();filtered.forEach(n=>{let k=groupKey(n);if(!groups.has(k))groups.set(k,{label:groupLabel(n),items:[]});groups.get(k).items.push(n)});root.innerHTML=[...groups.values()].map(g=>'<section class="nh-group"><div class="nh-group-title"><i></i>'+esc(g.label)+'</div>'+g.items.map(n=>{const summary=noteSummary(n);return '<article class="nh-memory-card"><div class="nh-memory-top"><span>'+esc(fmtTime(n.createdAt))+' · '+esc(n.type||'INSIGHT')+'</span><b>SMART NOTE · PRESERVED</b></div><div class="nh-memory-body"><h3>Intelligent Event</h3><p>'+esc(summary)+'</p></div><div class="nh-perspectives"><div class="nh-perspective"><b>HUMAN</b><span>'+esc(perspective(n,'HUMAN'))+'</span></div><div class="nh-perspective"><b>NAYA</b><span>'+esc(perspective(n,'NAYA'))+'</span></div><div class="nh-perspective"><b>MACHINE</b><span>'+esc(perspective(n,'MACHINE'))+'</span></div><div class="nh-perspective"><b>INTELLIGENT FEED</b><span>'+esc(perspective(n,'FEED'))+'</span></div></div></article>'}).join('')+'</section>').join('')}
function installNoteHeader(){const page=document.getElementById('page-notes');if(!page||document.getElementById('nhNoteHeader'))return;const head=page.querySelector('.pageHead');const box=document.createElement('div');box.id='nhNoteHeader';box.className='nh-note-head';box.innerHTML='<div><b>YOUR INTELLIGENCE MEMORY</b><strong>CAPTURED EVENTS, ORGANIZED FOR RECALL.</strong></div><span>Smart Notes is the memory/reporting surface — not a composer. Every preserved event remains one intelligence event: Human · Naya · Machine.</span>';head.insertAdjacentElement('afterend',box);const filters=document.getElementById('filters');const tf=document.createElement('div');tf.className='nh-timefilters';tf.id='nhTimeFilters';[['ALL TIME','ALL'],['BY HOUR','HOUR'],['BY DAY','DAY'],['BY MONTH','MONTH'],['BY YEAR','YEAR'],['HIGHLIGHTS','HIGHLIGHTS']].forEach(([label,val],i)=>{let b=document.createElement('button');b.className='nh-timefilter '+(i===2?'active':'');b.dataset.nhTime=val;b.textContent=label;tf.appendChild(b)});filters.insertAdjacentElement('afterend',tf);tf.addEventListener('click',e=>{let b=e.target.closest('[data-nh-time]');if(!b)return;document.querySelectorAll('.nh-timefilter').forEach(x=>x.classList.remove('active'));b.classList.add('active');mode=b.dataset.nhTime==='HIGHLIGHTS'?'HIGHLIGHTS':b.dataset.nhTime;if(mode==='HIGHLIGHTS')renderHighlights();else renderMemory()})}
function renderHighlights(){const root=document.getElementById('noteList');if(!root)return;const all=getNotes().sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));const today=dayKey(new Date().toISOString());const todayNotes=all.filter(n=>dayKey(n.createdAt)===today);const highlights=(todayNotes.length?todayNotes:all.slice(0,5));if(!highlights.length){root.innerHTML='<div class="nh-empty"><strong>Nothing highlighted yet.</strong><span>When preserved intelligence exists, the most relevant items for the day will appear here. No placeholder activity is presented as real.</span></div>';return}root.innerHTML='<div class="nh-report-state">'+(todayNotes.length?'TODAY · HIGHLIGHTED SOURCE EVENTS':'LATEST PRESERVED EVENTS · NO TODAY SOURCE EVENTS')+'</div>'+highlights.map(n=>'<article class="nh-memory-card"><div class="nh-memory-top"><span>'+esc(fmtDay(n.createdAt))+' · '+esc(fmtTime(n.createdAt))+'</span><b>'+esc(n.type||'INSIGHT')+'</b></div><div class="nh-memory-body"><h3>'+esc(noteSummary(n).slice(0,90)||'Intelligent Event')+'</h3><p>'+esc(noteSummary(n))+'</p></div></article>').join('')}
function reportMarkup(){const all=getNotes().sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));const today=dayKey(new Date().toISOString());const yesterday=dayKey(new Date(Date.now()-86400000).toISOString());const yesterdayNotes=all.filter(n=>dayKey(n.createdAt)===yesterday),todayNotes=all.filter(n=>dayKey(n.createdAt)===today);const source=yesterdayNotes.length?yesterdayNotes:todayNotes;const label=yesterdayNotes.length?'YESTERDAY · SOURCE-BACKED':'TODAY · SOURCE-BACKED';const sample=(arr,fallback)=>arr.length?arr.slice(0,3).map(n=>noteSummary(n)).join(' • '):fallback;const mattered=sample(source,'No verified source events yet.');const learned=sample(source.filter(n=>['LESSON','BREAKTHROUGH','INSIGHT','MISTAKE'].includes(n.type)),'No learning event is verified yet.');const carries=sample(source.filter(n=>['DECISION','GOAL','OPPORTUNITY','WIN'].includes(n.type)),'No carry-forward item is verified yet.');const next=sample(source.filter(n=>['QUESTION','MISTAKE','GOAL','OPPORTUNITY'].includes(n.type)),'No next-attention item is verified yet.');const truth=source.length?label:'EXAMPLE OUTPUT · NO VERIFIED REPORT FOUND';const prefix=source.length?'LOCAL SOURCE SYNTHESIS · NOT NAYA AI':'ILLUSTRATIVE FORMAT ONLY · NOT REAL ACTIVITY';return '<section class="nh-report"><div class="nh-report-head"><h2>Daily Intelligence Report</h2><span>'+prefix+'</span></div><div class="nh-report-state">'+truth+'</div><div class="nh-report-grid"><article class="nh-report-card"><h3>WHAT MATTERED</h3><p>'+esc(mattered)+'</p></article><article class="nh-report-card"><h3>WHAT WAS LEARNED</h3><p>'+esc(learned)+'</p></article><article class="nh-report-card"><h3>WHAT CARRIES FORWARD</h3><p>'+esc(carries)+'</p></article><article class="nh-report-card"><h3>WHAT DESERVES ATTENTION NEXT</h3><p>'+esc(next)+'</p></article></div></section>'}
function renderEnhancedReport(){const root=document.getElementById('nhReportPage');if(root)root.innerHTML=reportMarkup()}
function install(){const intelligenceNav=document.querySelector('[data-page="intelligence"]');if(intelligenceNav)intelligenceNav.innerHTML='<span class="ico">✦</span>Intelligence Library';installNoteHeader();const page=document.getElementById('page-notes');if(page){const p=page.querySelector('.pageHead p');if(p)p.textContent='Your living intelligence memory — organized by time, searchable, highlighted, and ready for compounding.'}const rp=document.getElementById('page-reports');if(rp){const oldGrid=rp.querySelector('.grid2');if(oldGrid)oldGrid.style.display='none';renderEnhancedReport();const btn=document.getElementById('generateReport');if(btn){btn.textContent='REFRESH REPORT';btn.onclick=renderEnhancedReport}}document.querySelectorAll('#filters .filter').forEach(b=>b.addEventListener('click',()=>setTimeout(()=>{if(mode!=='HIGHLIGHTS')renderMemory()},0)));const search=document.getElementById('noteSearch');if(search)search.addEventListener('input',()=>{if(mode!=='HIGHLIGHTS')renderMemory()});const ip=document.getElementById('page-intelligence');if(ip&&!document.getElementById('nhLibrary')){const wrap=document.createElement('div');wrap.id='nhLibrary';wrap.className='grid2';wrap.innerHTML=[['WHAT IS THE INTELLIGENT HUB?','A living, searchable intelligence library/feed: CAPTURE → DISTILL → ORGANIZE → REMEMBER → FIND → COMPOUND.'],['WHAT IS A SMART NOTE?','One intelligence event containing Human, Naya, and Machine perspectives. The original human meaning is preserved.'],['WHAT DOES NAYA EXPLAIN?','Interpretation, guidance, and synthesis when the production intelligence service is actually connected. No fabricated AI output.'],['WHAT DOES THE SYSTEM KNOW?','Verified event metadata, timestamps, types, privacy boundaries, source state, and whatever authenticated services actually return.'],['WHAT COMPOUNDS?','Meaningful events that remain findable and comparable over time, allowing patterns and lessons to carry forward.'],['WHERE DOES EVERYTHING LIVE?','Smart Notes holds preserved memory; the Intelligent Feed makes it legible; Daily Intelligence compresses it; Collective governs what may be shared.'],['HOW IS PRIVACY HANDLED?','Private by default · shared by choice · collective by consent · public by decision. Raw private notes do not silently become collective content.'],['HOW DO I FIND OLD INTELLIGENCE?','Use Smart Notes search and the hour/day/month/year organization. Highlights surface the most relevant preserved items.'],['WHAT IS THE DAILY REPORT?','A truthful compression of what mattered, what was learned, what carries forward, and what deserves attention next.'],['WHAT IS THE COLLECTIVE?','The consent boundary for eligible de-identified wisdom. Participation is explicit, never silent.']].map(x=>'<section class="feature colorCard" style="--tone:var(--sapphire)"><div class="eyebrow">REFERENCE</div><h2>'+esc(x[0])+'</h2><p>'+esc(x[1])+'</p></section>').join('');ip.appendChild(wrap)}if(document.getElementById('page-notes')?.classList.contains('active'))renderMemory()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install);else install();
})();
</script>
'''
if 'id="nayanet-v7-refinement-runtime"' not in s:
    s=s.replace('</body>',js+'</body>',1)

p.write_text(s,encoding='utf-8')
print(f'patched NAYAHUB.html: {len(s):,} bytes')
